te": "Two departmental elective slots per semester.", "position": 14}, {"level": 500, "semester": 2, "code": "CPE 562", "title": "Ad hoc and Sensor Networks", "units": 2, "status": "E", "lecture_hours": 45, "practical_hours": 0, "elective_group": "Departmental elective - Option C: Computer Communication and Networks", "note": "Two departmental elective slots per semester.", "position": 15}, {"level": 500, "semester": 2, "code": "CPE 572", "title": "Internet and Multimedia Software Development", "units": 2, "status": "E", "lecture_hours": 45, "practical_hours": 0, "elective_group": "Departmental elective - Option D: Software Engineering and Cyber Security", "note": "Two departmental elective slots per semester.", "position": 16}, {"level": 500, "semester": 2, "code": "CPE 592", "title": "Computer Forensics", "units": 2, "status": "E", "lecture_hours": 45, "practical_hours": 0, "elective_group": "Departmental elective - Option D: Software Engineering and Cyber Security", "note": "Two departmental elective slots per semester.", "position": 17}]$data$::jsonb) as r(level int,semester int,code text,title text,units int,status text,lecture_hours int,practical_hours int,elective_group text,note text,position int);
create temp table cpe_scope on commit drop as
select d.id department_id,d.university_id,l.id level_id,l.sort_order level,s.id semester_id,s.sort_order semester
from public.departments d join public.universities u on u.id=d.university_id
join public.levels l on l.university_id=u.id and l.active and l.sort_order in(100,200,300,400,500)
join public.academic_periods ap on ap.university_id=u.id and ap.label='2026/2027' and ap.active
join public.semesters s on s.academic_period_id=ap.id and s.active and s.sort_order in(1,2)
where d.name='Computer Engineering' and d.active and u.slug='adeleke-university-ede-osun-state';
create temp table cpe_other on commit drop as select o.* from public.course_offerings o where not exists(select 1 from cpe_scope s where s.department_id=o.department_id and s.level_id=o.level_id and s.semester_id=o.semester_id);
create temp table cpe_existing on commit drop as select o.id,o.course_id,o.department_id,o.level_id,o.semester_id from public.course_offerings o join cpe_scope s using(department_id,level_id,semester_id);
create temp table cpe_enrollments on commit drop as select * from public.enrollments;
do $$ begin
if (select count(*) from cpe_scope)<>10 or (select count(*) from cpe_requested)<>102 then raise exception 'CPE source/scope mismatch'; end if;
end $$;
insert into public.courses(code,title) select distinct code,title from cpe_requested on conflict(code) do nothing;
update public.courses set title='Introduction to Computer Engineering Laboratory' where code='AUE-CPE 101' and title like '%pending confirmation%';
insert into public.curriculum_courses(university_id,department_id,level_id,semester_number,course_id,unit_count,requirement_status,position,source_reference,lecture_hours,practical_hours,elective_group,source_code,source_title)
select s.university_id,s.department_id,s.level_id,r.semester,c.id,r.units,r.status,r.position,'CPE List of courses 100L to 500L (2026_2027 session).pdf. '||coalesce(r.note,''),r.lecture_hours,r.practical_hours,r.elective_group,r.code,r.title
from cpe_requested r join cpe_scope s using(level,semester) join public.courses c on c.code=r.code
on conflict(department_id,level_id,semester_number,course_id) do update set unit_count=excluded.unit_count,requirement_status=excluded.requirement_status,position=excluded.position,source_reference=excluded.source_reference,lecture_hours=excluded.lecture_hours,practical_hours=excluded.practical_hours,elective_group=excluded.elective_group,source_code=excluded.source_code,source_title=excluded.source_title,active=true;
insert into public.course_offerings(course_id,university_id,department_id,level_id,semester_id,status,unit_count,requirement_status,lecture_hours,practical_hours,elective_group,source_code,source_title)
select c.id,s.university_id,s.department_id,s.level_id,s.semester_id,'published',r.units,r.status,r.lecture_hours,r.practical_hours,r.elective_group,r.code,r.title
from cpe_requested r join cpe_scope s using(level,semester) join public.courses c on c.code=r.code
on conflict(course_id,department_id,level_id,semester_id) do update set status='published',unit_count=excluded.unit_count,requirement_status=excluded.requirement_status,lecture_hours=excluded.lecture_hours,practical_hours=excluded.practical_hours,elective_group=excluded.elective_group,source_code=excluded.source_code,source_title=excluded.source_title;
do $$ begin
if (select count(*) from cpe_requested r join cpe_scope s using(level,semester) join public.courses c on c.code=r.code join public.course_offerings o on o.course_id=c.id and o.department_id=s.department_id and o.level_id=s.level_id and o.semester_id=s.semester_id where o.status='published' and o.unit_count=r.units and o.requirement_status=r.status and o.source_title=r.title and o.elective_group is not distinct from r.elective_group and o.lecture_hours is not distinct from r.lecture_hours and o.practical_hours is not distinct from r.practical_hours)<>102 then raise exception 'CPE offerings verification failed'; end if;
if exists(select * from cpe_other except select * from public.course_offerings) then raise exception 'Unrelated offerings changed'; end if;
if exists(select * from cpe_existing except select id,course_id,department_id,level_id,semester_id from public.course_offerings) then raise exception 'Existing CPE IDs changed'; end if;
if exists(select * from cpe_enrollments except select * from public.enrollments) then raise exception 'Enrollments changed'; end if;
end $$;
